import jax, jax.numpy as jnp
jax.config.update("jax_enable_x64", True)
V = 7
k = jax.random.key(0)
z = jax.random.normal(k, (V,))
p = jax.nn.softmax(z)
zq = z + 0.3 * jax.random.normal(jax.random.key(1), (V,))
q = jax.nn.softmax(zq)
def grad_orig(z, y):   # -A*log p(y), A=1
    return jax.grad(lambda z: -jax.nn.log_softmax(z)[y])(z)
def grad_cv(z, y):     # -A*(log p(y) - sum_v q(v) log p(v))
    return jax.grad(lambda z: -(jax.nn.log_softmax(z)[y] - (q * jax.nn.log_softmax(z)).sum()))(z)
def expect(g):
    return sum(q[y] * g(z, y) for y in range(V))
def expect_p(g):
    return sum(p[y] * g(z, y) for y in range(V))
print("on-policy q=p, original:", jnp.abs(sum(p[y]*grad_orig(z,y) for y in range(V))).max())
print("mismatch, original E_q[grad] :", expect(grad_orig))
print("   predicted -(q-p) (loss grad) :", -(q - p))
print("mismatch, control variate E_q[grad]:", expect(grad_cv))
EOF
